  if (!input) return "";
  let result = "";
  let count = 1;

  for (let i = 0; i < input.length; i++) {
    if (i + 1 < input.length && input[i] === input[i + 1]) {
      count++;
    } else {
      result += (count > 1 ? count : "") + input[i];
      count = 1;
    }
  }

  return result;
