export function decode(input: string): string {
  if (!input) return "";
  let result = "";
  let countStr = "";

  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    if (/\\d/.test(char)) {
      countStr += char;
    } else {
      const count = countStr.length > 0 ? parseInt(countStr, 10) : 1;
      result += char.repeat(count);
      countStr = "";
    }
  }

  return result;
}
